//! Fork: the stored import of a Claude Code session (specs/fork-rust-imported-history.md) against rows Node wrote
//! (`fixtures/imported_history_golden.json`, regenerated by `fixtures/gen-imported-history.mts`).
use rust_cli_kernel_api::ids::SessionId;
use rust_cli_kernel_api::message::{ContentBlock, Message, StopReason, UserOrigin};
use rust_cli_kernel_api::store::{
    ImportedHistory, ImportedMessage, SessionStore, StoreError, StoreQueries,
};
use serde_json::{Value, json};

use crate::NodeStore;
use crate::tests::{FIXTURE_VERSION, TestStore, fixed_ids, started};

fn golden() -> Value {
    serde_json::from_str(include_str!("fixtures/imported_history_golden.json")).unwrap()
}

/// The history the golden generator imported.
fn history(golden: &Value) -> ImportedHistory {
    let input = &golden["history"];
    ImportedHistory {
        title: input["title"].as_str().map(str::to_owned),
        created_at: input["createdAt"].as_u64(),
        updated_at: input["updatedAt"].as_u64(),
        messages: input["messages"]
            .as_array()
            .unwrap()
            .iter()
            .map(|message| ImportedMessage {
                assistant: message["role"] == "assistant",
                content: message["content"].as_str().unwrap().to_owned(),
                timestamp: message["timestamp"].as_u64(),
            })
            .collect(),
    }
}

fn texts(messages: &[Message]) -> Vec<(String, String)> {
    messages
        .iter()
        .map(|message| match message {
            Message::User(user) => (
                "user".to_owned(),
                match &user.content[..] {
                    [ContentBlock::Text { text }] => text.clone(),
                    other => panic!("one text block expected: {other:?}"),
                },
            ),
            Message::Assistant(assistant) => (
                "assistant".to_owned(),
                match &assistant.content[..] {
                    [ContentBlock::Text { text }] => text.clone(),
                    other => panic!("one text block expected: {other:?}"),
                },
            ),
            other => panic!("unexpected message {other:?}"),
        })
        .collect()
}

fn expected_texts() -> Vec<(String, String)> {
    [
        ("user", "hello"),
        ("assistant", "hi"),
        ("user", "again"),
        ("assistant", "ok"),
        ("assistant", "second answer"),
    ]
    .into_iter()
    .map(|(role, text)| (role.to_owned(), text.to_owned()))
    .collect()
}

/// The rows the import writes are the rows Node wrote for the same input: `data` byte for byte, and the columns Node's
/// `createSession` / `saveMessage` / `savePart` set from the input.
#[tokio::test]
async fn the_rows_equal_the_ones_node_wrote() {
    let golden = golden();
    let t = TestStore::new();
    started(&t, "sess_imp1").await;
    t.store
        .import_history(&SessionId::new("sess_imp1"), &history(&golden))
        .await
        .unwrap();

    let session = t.rows(
        "select title, title_source, slug, time_created, time_title_updated, permission from session where id = 'sess_imp1'",
    );
    let node = &golden["session"];
    assert_eq!(
        session,
        vec![vec![
            node["title"].clone(),
            node["title_source"].clone(),
            node["slug"].clone(),
            node["time_created"].clone(),
            node["time_title_updated"].clone(),
            node["permission"].clone(),
        ]]
    );
    let messages = t
        .rows("select id, time_created, time_updated, data from message order by time_created, id");
    let expected: Vec<Vec<Value>> = golden["messages"]
        .as_array()
        .unwrap()
        .iter()
        .map(|row| {
            vec![
                row["id"].clone(),
                row["time_created"].clone(),
                row["time_updated"].clone(),
                row["data"].clone(),
            ]
        })
        .collect();
    assert_eq!(messages, expected);
    let parts =
        t.rows("select id, message_id, time_created, data from part order by time_created, id");
    let expected: Vec<Vec<Value>> = golden["parts"]
        .as_array()
        .unwrap()
        .iter()
        .map(|row| {
            vec![
                row["id"].clone(),
                row["message_id"].clone(),
                row["time_created"].clone(),
                row["data"].clone(),
            ]
        })
        .collect();
    assert_eq!(parts, expected);
}

/// What Node wrote loads here: the text of both roles, the stored model and finish, the title and creation time.
#[tokio::test]
async fn a_node_written_import_loads_here() {
    let golden = golden();
    let t = TestStore::new();
    started(&t, "sess_imp1").await;
    // The session as Node left it: the golden's session columns and message rows, written by another connection.
    let conn = t.connection();
    let session = &golden["session"];
    conn.execute(
        "update session set title = ?, title_source = ?, slug = ?, time_created = ?, time_title_updated = ? where id = 'sess_imp1'",
        rusqlite::params![
            session["title"].as_str().unwrap(),
            session["title_source"].as_str().unwrap(),
            session["slug"].as_str().unwrap(),
            session["time_created"].as_i64().unwrap(),
            session["time_title_updated"].as_i64().unwrap(),
        ],
    )
    .unwrap();
    for row in golden["messages"].as_array().unwrap() {
        conn.execute(
            "insert into message (id, session_id, time_created, time_updated, data) values (?, 'sess_imp1', ?, ?, ?)",
            rusqlite::params![
                row["id"].as_str().unwrap(),
                row["time_created"].as_i64().unwrap(),
                row["time_updated"].as_i64().unwrap(),
                row["data"].as_str().unwrap(),
            ],
        )
        .unwrap();
    }
    for row in golden["parts"].as_array().unwrap() {
        conn.execute(
            "insert into part (id, message_id, session_id, time_created, time_updated, data) values (?, ?, 'sess_imp1', ?, ?, ?)",
            rusqlite::params![
                row["id"].as_str().unwrap(),
                row["message_id"].as_str().unwrap(),
                row["time_created"].as_i64().unwrap(),
                row["time_created"].as_i64().unwrap(),
                row["data"].as_str().unwrap(),
            ],
        )
        .unwrap();
    }
    drop(conn);
    let loaded = t.store.load(&SessionId::new("sess_imp1")).await.unwrap();
    assert_eq!(loaded.meta.title, "Imported chat");
    assert_eq!(loaded.meta.created_at_ms, 1000);
    assert_eq!(texts(&loaded.messages), expected_texts());
    let Message::Assistant(reply) = &loaded.messages[1] else {
        panic!("assistant expected");
    };
    assert_eq!(reply.model, "m");
    assert_eq!(reply.stop_reason, Some(StopReason::EndTurn));
    let Message::User(first) = &loaded.messages[0] else {
        panic!("user expected");
    };
    assert_eq!(first.origin, UserOrigin::Human);
}

/// The reverse: what this store wrote loads to the same messages as the Node rows do.
#[tokio::test]
async fn a_rust_written_import_loads_the_same() {
    let golden = golden();
    let t = TestStore::new();
    started(&t, "sess_imp1").await;
    t.store
        .import_history(&SessionId::new("sess_imp1"), &history(&golden))
        .await
        .unwrap();
    let loaded = t.store.load(&SessionId::new("sess_imp1")).await.unwrap();
    assert_eq!(loaded.meta.title, "Imported chat");
    assert_eq!(loaded.meta.created_at_ms, 1000);
    assert_eq!(texts(&loaded.messages), expected_texts());
    let Message::Assistant(reply) = &loaded.messages[1] else {
        panic!("assistant expected");
    };
    assert_eq!(reply.model, "m");
    assert_eq!(reply.stop_reason, Some(StopReason::EndTurn));
}

/// A deferred draft gets its row in the import's own transaction.
#[tokio::test]
async fn a_draft_is_persisted_by_the_import() {
    let golden = golden();
    let mut t = TestStore::new();
    t.store = NodeStore::new(t.store.paths().clone(), fixed_ids(&t.source))
        .with_version(FIXTURE_VERSION)
        .with_deferred_drafts();
    started(&t, "sess_imp1").await;
    let id = SessionId::new("sess_imp1");
    assert!(t.store.is_draft(&id).await.unwrap());
    t.store
        .import_history(&id, &history(&golden))
        .await
        .unwrap();
    assert!(!t.store.is_draft(&id).await.unwrap());
    let loaded = t.store.load(&id).await.unwrap();
    assert_eq!(loaded.meta.title, "Imported chat");
    assert_eq!(texts(&loaded.messages), expected_texts());
}

/// Node `title?.trim() || "Imported session"`, and the first timestamps: the creation time is the first message's, the
/// update time the last one's.
#[tokio::test]
async fn a_blank_title_and_missing_times_fall_back() {
    let t = TestStore::new();
    started(&t, "sess_imp2").await;
    let history = ImportedHistory {
        title: Some("   ".to_owned()),
        created_at: None,
        updated_at: None,
        messages: vec![
            ImportedMessage {
                assistant: false,
                content: "q".to_owned(),
                timestamp: Some(300),
            },
            ImportedMessage {
                assistant: true,
                content: "a".to_owned(),
                timestamp: Some(400),
            },
        ],
    };
    t.store
        .import_history(&SessionId::new("sess_imp2"), &history)
        .await
        .unwrap();
    let rows = t.rows(
        "select title, time_created, time_title_updated, slug from session where id = 'sess_imp2'",
    );
    assert_eq!(
        rows,
        vec![vec![
            json!("Imported session"),
            json!(300),
            json!(400),
            json!("sess_imp2")
        ]]
    );
}

#[tokio::test]
async fn an_unknown_session_is_not_found() {
    let t = TestStore::new();
    let error = t
        .store
        .import_history(&SessionId::new("sess_none"), &ImportedHistory::default())
        .await
        .unwrap_err();
    assert!(matches!(error, StoreError::NotFound { .. }), "{error:?}");
}
